@staticmethod
def inValues(subject, *choices):
    if not choices:
        return 0
    value = subject()
    result = 0
    for choice in choices:
        equal = $SQL$.binary("equal", value, choice())
        if equal == 1:
            return 1
        if equal is None:
            result = None
    return result

javascript:
static inValues(subject, ...choices) {
  if (choices.length === 0) return 0;
  const value = subject();
  let result = 0;
  for (const choice of choices) {
    const equal = $SQL$.binary("equal", value, choice());
    if (equal === 1) return 1;
    if (equal === null) result = null;
  }
  return result;
}

